// EC_Validate_Input — v1.0
// Purpose: Validate and adapt the inbound ExecutionContextInitRequest.
// Accepts both flat and nested shapes.
// Nested: { request: { tenant_id, thread_id, trigger_message_id, resolution_method, resolved_at, idempotency_key } }
// Flat:   { tenant_id, thread_id, trigger_message_id, resolution_method, resolved_at, idempotency_key }
// Output: validated request with _valid='true' (string) or _valid='false' with _error.

const items = $input.all();
const raw = (items[0] && items[0].json) || {};

// Adapter: detect nested vs flat
let req;
if (raw.request && typeof raw.request === 'object') {
  req = {
    tenant_id: raw.request.tenant_id,
    thread_id: raw.request.thread_id,
    trigger_message_id: raw.request.trigger_message_id,
    resolution_method: raw.request.resolution_method,
    resolved_at: raw.request.resolved_at,
    idempotency_key: raw.request.idempotency_key || raw.idempotency_key || null
  };
} else {
  req = {
    tenant_id: raw.tenant_id,
    thread_id: raw.thread_id,
    trigger_message_id: raw.trigger_message_id,
    resolution_method: raw.resolution_method || null,
    resolved_at: raw.resolved_at || null,
    idempotency_key: raw.idempotency_key || null
  };
}

// UUID v4/any-variant permissive regex (aligned with PostgreSQL uuid cast)
const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

function invalid(code, missing) {
  return [{
    json: {
      _valid: 'false',
      _error: code,
      _missing_fields: missing || [],
      _request: req
    }
  }];
}

const required = ['tenant_id', 'thread_id', 'trigger_message_id'];
const missing = required.filter(f => req[f] === undefined || req[f] === null || req[f] === '');
if (missing.length > 0) {
  return invalid('INVALID_INPUT', missing);
}

for (const f of required) {
  if (typeof req[f] !== 'string' || !UUID_RE.test(req[f])) {
    return invalid('INVALID_UUID', [f]);
  }
}

// Optional resolved_at: if provided, must be valid ISO 8601-ish
if (req.resolved_at && isNaN(Date.parse(req.resolved_at))) {
  return invalid('INVALID_RESOLVED_AT', ['resolved_at']);
}

// Derive idempotency_key deterministically if not provided
const idemp = req.idempotency_key && String(req.idempotency_key).trim().length > 0
  ? String(req.idempotency_key)
  : (req.tenant_id + ':' + req.trigger_message_id + ':exec_ctx:v1');

// Guard VARCHAR(300) upper bound on idempotency_key
if (idemp.length > 300) {
  return invalid('IDEMPOTENCY_KEY_TOO_LONG', ['idempotency_key']);
}

return [{
  json: {
    _valid: 'true',
    tenant_id: req.tenant_id,
    thread_id: req.thread_id,
    trigger_message_id: req.trigger_message_id,
    resolution_method: req.resolution_method || null,
    resolved_at: req.resolved_at || null,
    _idempotency_key: idemp
  }
}];

// EC_Build_Init_Payload — v1.0
// Builds the exact insert payload for execution_contexts.
// Guarantees live-schema alignment:
//   status = 'initialized'
//   pending_steps = []
//   completed_steps = []
//   expires_at = now + 15 minutes (TTL)

const req = $input.all()[0].json;
const nowIso = new Date().toISOString();
const ttlMs = 15 * 60 * 1000; // 15 minutes
const expiresIso = new Date(Date.now() + ttlMs).toISOString();

return [{
  json: {
    tenant_id: req.tenant_id,
    thread_id: req.thread_id,
    trigger_message_id: req.trigger_message_id,
    status: 'initialized',
    pending_steps: [],
    completed_steps: [],
    idempotency_key: req._idempotency_key,
    expires_at: expiresIso,
    // Passthrough for downstream observability
    resolution_method: req.resolution_method || null,
    resolved_at: req.resolved_at || null,
    _now: nowIso
  }
}];

// EC_Return_Result — v1.0
// Reads the canonical row from EC_Load_Existing_Context and shapes the canonical
// ExecutionContext output contract.
// Note: reads via $('EC_Load_Existing_Context') to avoid coupling to upstream
// branching semantics. Classifies empty row as INTERNAL_LOAD_FAILED.

const loaded = $('EC_Load_Existing_Context').all();
const src = (loaded[0] && loaded[0].json) || null;

if (!src || !src.id) {
  return [{
    json: {
      id: null,
      tenant_id: null,
      thread_id: null,
      trigger_message_id: null,
      status: 'failed',
      current_goal: null,
      current_plan_ref: null,
      pending_steps: [],
      completed_steps: [],
      created_at: null,
      updated_at: null,
      error: {
        code: 'INTERNAL_LOAD_FAILED',
        message: 'Execution context could not be loaded after upsert'
      },
      module_name: 'execution_context_init',
      result_type: 'error',
      status_kind: 'failed'
    }
  }];
}

return [{
  json: {
    id: src.id,
    tenant_id: src.tenant_id,
    thread_id: src.thread_id,
    trigger_message_id: src.trigger_message_id,
    status: src.status,
    current_goal: src.current_goal === undefined ? null : src.current_goal,
    current_plan_ref: src.current_plan_ref === undefined ? null : src.current_plan_ref,
    pending_steps: src.pending_steps || [],
    completed_steps: src.completed_steps || [],
    created_at: src.created_at,
    updated_at: src.updated_at,
    error: null,
    module_name: 'execution_context_init',
    result_type: 'state',
    status_kind: 'success'
  }
}];

// EC_Return_Error — v1.0
// Error-shaped output for invalid-input path.

const errItem = $input.all()[0] && $input.all()[0].json || {};
const req = errItem._request || {};

return [{
  json: {
    id: null,
    tenant_id: req.tenant_id || null,
    thread_id: req.thread_id || null,
    trigger_message_id: req.trigger_message_id || null,
    status: 'failed',
    current_goal: null,
    current_plan_ref: null,
    pending_steps: [],
    completed_steps: [],
    created_at: null,
    updated_at: null,
    error: {
      code: errItem._error || 'INVALID_INPUT',
      missing_fields: errItem._missing_fields || []
    },
    module_name: 'execution_context_init',
    result_type: 'error',
    status_kind: 'failed'
  }
}];

